/* 隠しBGM (許諾未確認 — 公開時はこのファイルを削除すればビルドから消える) */
const YAMAHA_BGM='data:audio/mpeg;base64,';

/* ---- 隠しBGM プレイヤー (Sランク解説画面のみ / 非ループ) ---- */
const BGM={
  a:null,
  play(){
    if(typeof YAMAHA_BGM==='undefined')return;
    if(typeof SFX!=='undefined'&&SFX.muted)return;
    this.stop();
    this.a=new Audio(YAMAHA_BGM);
    this.a.volume=.55;this.a.loop=false;
    this.a.play().catch(()=>{});
  },
  stop(){if(this.a){try{this.a.pause();}catch(e){}this.a=null;}}
};
